#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

struct FlowEdge {
    int to, capacity, flow, rev;
    FlowEdge() {}
    FlowEdge(int t, int c, int f, int r) : to(t), capacity(c), flow(f), rev(r) {}
};

const int MAXN = 121;
vector<FlowEdge> adj[MAXN];
int level[MAXN], ptr[MAXN], s, t, n;
queue<int> q;

void addEdge(int v, int u, int cap) {
    adj[v].push_back(FlowEdge(u, cap, 0, (int)adj[u].size()));
    adj[u].push_back(FlowEdge(v, 0, 0, (int)adj[v].size() - 1));
}

bool buildLevelGraph() {
    for (int i = 0; i <= t; ++i) level[i] = -1;
    level[s] = 0;
    q = queue<int>();
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : adj[v]) {
            if (level[e.to] < 0 && e.capacity - e.flow > 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] >= 0;
}

int sendFlow(int v, int flow) {
    if (v == t) return flow;
    for (int &i = ptr[v]; i < (int)adj[v].size(); ++i) {
        auto &e = adj[v][i];
        if (level[e.to] == level[v] + 1 && e.capacity - e.flow > 0) {
            int pushed = sendFlow(e.to, min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                adj[e.to][e.rev].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (buildLevelGraph()) {
        for (int i = 0; i <= t; ++i) ptr[i] = 0;
        int pushed;
        while ((pushed = sendFlow(s, 1e9)) > 0) totalFlow += pushed;
    }
    return totalFlow;
}

int main() {
    int size, tbad;
    cin >> size >> tbad;
    char maze[N][N], maze_b[N][N];
    int px, py;
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j) {
            cin >> maze[i][j];
            if (maze[i][j] == 'Z') px = i, py = j;
        }
    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j)
            cin >> maze_b[i][j];

    s = 0;
    t = 2 * size * size + 1;

    for (int i = 0; i < size; ++i)
        for (int j = 0; j < size; ++j) {
            int u = i * size + j + 1;
            if (maze[i][j] != '0') addEdge(s, u, maze[i][j] - '0');
            if (maze_b[i][j] != '0') addEdge(u + size * size, t, maze_b[i][j] - '0');
        }

    cout << maxFlow() << endl;
    return 0;
}
